["names"] = {
},
["spellIds"] = {
},
["custom"] = "function (e, arg1)\n    if e == \"PSY_WHEEL_DECIDE_KEYS_OBTAINED\" then\n        aura_env.keys = arg1\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_GO\" then\n        local selectedIndex = aura_env.decide()\n        C_Timer.After(aura_env.config.spinTime, function() \n                WeakAuras.ScanEvents(\"PSY_WHEEL_DECIDE_KEYS_DECIDED\", selectedIndex)\n        end)\n    end\nend",
