["Warband Warbank Gold Sync"] = {
["outline"] = "OUTLINE",
["wagoID"] = "mvvUWojna",
["parent"] = "Utilities",
["preferToUpdate"] = true,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/mvvUWojna/11",
["actions"] = {
["start"] = {
["custom"] = "",
["do_custom"] = false,
},
["init"] = {
["custom"] = "-- debug\n-- print(variable)\n-- DevTools_Dump(table)\n\n-- Constants\nlocal COPPER_PER_SILVER = 100\nlocal SILVER_PER_GOLD = 100\nlocal COPPER_PER_GOLD = COPPER_PER_SILVER * SILVER_PER_GOLD\nlocal WARBANK = 2 -- bankType Account (Warbank)\nlocal C_Bank = C_Bank\n-- gold * silver * copper\naura_env.desiredCopper = aura_env.config[\"defaultDesiredGold\"] * COPPER_PER_GOLD;\n\n-- Helper\nlocal function sanitizeCharacterNameRealm(input)\n    return string.lower(input:gsub(\"[ %']\", \"\"))\nend\n\n-- Get current Character-Realm\naura_env.currentCharacterNameRealm = sanitizeCharacterNameRealm(GetUnitName(\"player\") .. \"-\" .. GetRealmName())\n\n-- Create Ignore list\naura_env.ignoreCharactersTable = {}\nfor name in string.gmatch(aura_env.config[\"ignoreList\"], '([^,]+)') do\n    aura_env.ignoreCharactersTable[sanitizeCharacterNameRealm(name)] = true\nend\n\n-- Create Override list\naura_env.overrideCharactersTable = {}\nfor _, entry in ipairs(aura_env.config.overrideList) do\n    table.insert(aura_env.overrideCharactersTable, sanitizeCharacterNameRealm(entry.characterNameRealm))\nend\n\n-- Operation\naura_env.WarbankOperation = function(differenceCopper)\n    -- If operation not necessary\n    if differenceCopper == 0 then return end\n    -- If operation is necessary\n    if differenceCopper ~= 0 then\n        local action, amount = nil, math.abs(differenceCopper)\n        \n        -- If I don't have enough, withdraw\n        if differenceCopper > 0 and C_Bank.CanWithdrawMoney(WARBANK) then\n            -- I can't withdraw more than I have deposited\n            -- Withdraw what I can\n            local maxDeposited = C_Bank.FetchDepositedMoney(WARBANK)\n            amount = math.min(maxDeposited, differenceCopper)\n            C_Bank.WithdrawMoney(WARBANK, amount)\n            action = \"withdrew\"\n        end    \n        -- If I have enough, deposit\n        if differenceCopper < 0 and C_Bank.CanDepositMoney(WARBANK) then\n            C_Bank.DepositMoney(WARBANK, amount)\n            action = \"deposited\"\n        end\n        -- If printing is enabled\n        if action and aura_env.config.printOperationEnabled then\n            SendSystemMessage(string.format(\"[Warbank] You %s: %s\", action, GetCoinTextureString(amount)))\n        end\n    end\nend\n\n-- Override Operation\naura_env.WarBankOperationOverride = function(currentCopper)\n    -- If override entries exist, match characterNameRealm\n    for _, overrideEntry in ipairs(aura_env.config.overrideList) do\n        if sanitizeCharacterNameRealm(overrideEntry.characterNameRealm) == aura_env.currentCharacterNameRealm then\n            aura_env.differenceCopper = (overrideEntry.desiredGold * COPPER_PER_GOLD) - currentCopper\n            aura_env.WarbankOperation(aura_env.differenceCopper)\n            return\n        end\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["custom_hide"] = "timed",
["duration"] = "1",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(event, ...)  \n    if event == \"BANKFRAME_OPENED\"  then\n        -- If character ignored, return early\n        if aura_env.ignoreCharactersTable[aura_env.currentCharacterNameRealm] then\n            return\n        end\n        \n        -- Get current money difference\n        aura_env.currentCopper = GetMoney();\n        aura_env.differenceCopper = aura_env.desiredCopper - aura_env.currentCopper\n        \n        -- Override operation\n        if (function() for _, v in ipairs(aura_env.overrideCharactersTable) do if v == aura_env.currentCharacterNameRealm then return true end end end)() then\n            aura_env.WarBankOperationOverride(aura_env.currentCopper)\n            return\n        end\n        \n        -- Normal operation\n        aura_env.WarbankOperation(aura_env.differenceCopper)\n    end\nend",
