["init"] = {
["custom"] = "aura_env.soundHandle = -1\n\naura_env.sounds = {\n    [1] = 143176, --Dolly\n    [2] = 127965, --rollercoaster\n    [3] = 175995,\n    [4] = 15853,\n    [5] = 17346,\n    [6] = 175411\n    \n}\n\naura_env.getSoundId = function()\n    local selectedIndex = math.random(1, #aura_env.sounds)\n    return aura_env.sounds[selectedIndex]\nend",
