{
["trigger"] = {
["type"] = "custom",
["custom"] = "function(e,...)\n    if e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _,_,_,_,_,_,_,destGUID = ...\n        \n        for i, g in pairs(aura_env.markersInUse) do\n            if destGUID == g then\n                aura_env.markersInUse[i] = nil\n            end\n        end\n        \n    elseif e == \"TRIGGER\" then\n        local _, s = ...\n        \n        for _, v in pairs(s) do\n            if v.unit and v.raidMarkIndex then\n                local GUID = UnitGUID(v.unit)\n                \n                if aura_env.markersToUse[v.raidMarkIndex] then\n                    aura_env.markersInUse[v.raidMarkIndex] = GUID\n                else\n                    for i, g in pairs(aura_env.markersInUse) do\n                        if g == GUID then\n                            aura_env.markersInUse[i] = nil                            \n                            break\n                        end\n                    end\n                    \n                    for i = 1, #aura_env.markersToUse do\n                        if aura_env.markersToUse[i] and not aura_env.markersInUse[i] then\n                            SetRaidTarget(v.unit, i)\n                          --  aura_env.markersInUse[i] = GUID\n                            break\n                        end\n                    end\n                end \n            end   \n        end\n    end\nend\n\n\n",
