["Glow Raid Frames Dispellables"] = {
["glow"] = false,
["text1FontSize"] = 12,
["xOffset"] = -186.1663818359375,
["displayText"] = " ",
["yOffset"] = -197.6665649414063,
["anchorPoint"] = "CENTER",
["url"] = "https://wago.io/S1h_oOZDX/3",
["actions"] = {
["start"] = {
["custom"] = "local frame = aura_env.GetFrame(aura_env.state.name)\nif frame then\n    aura_env.Glow(frame, true)\nend\n\n\n\n\n\n\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "local frame = aura_env.GetFrame(aura_env.state.name)\nif frame then\n    aura_env.Glow(frame, false)\nend\n\n\n\n\n",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local custom_glow = {\n  enable = true,                       -- use custom glow style from Deezo\n  red = 1,\n  green = 1,\n  blue = 1,\n  alpha = 1,\n  N = 14,                              -- number of particle groups (each groups contains 4 particles)\n  frequency = 0.3,                       -- time for biggest particle to travel around region\n  scale = 1,                           -- scale of particles\n  xOffset = 0,\n  yOffset = 0\n}\n\nlocal frame_priority = {\n  -- raid frames\n  [1] = \"^Vd1\", -- vuhdo\n  [2] = \"^Healbot\", -- healbot\n  [3] = \"^GridLayout\", -- grid\n  [4] = \"^Grid2Layout\", -- grid2\n  [5] = \"^ElvUF_RaidGroup\", -- elv\n  [6] = \"^oUF_bdGrid\", -- bdgrid\n  [7] = \"^LimeGroup\", -- lime\n  [9] = \"^CompactRaid\", -- blizz\n}\n\nlocal can_dispell_table = {\n  [\"DRUID\"] = { \n    [1] = { [\"Poison\"] = true, [\"Curse\"] = true, }, -- balance\n    [2] = { [\"Poison\"] = true, [\"Curse\"] = true, }, -- feral\n    [3] = { [\"Poison\"] = true, [\"Curse\"] = true, }, -- guardian\n    [4] = { [\"Poison\"] = true, [\"Curse\"] = true, [\"Magic\"] = true, }, -- resto\n  },\n  [\"MONK\"] = { \n    [1] = { [\"Poison\"] = true, [\"Disease\"] = true, }, -- brew\n    [2] = { [\"Poison\"] = true, [\"Disease\"] = true, [\"Magic\"] = true, }, -- mist\n    [3] = { [\"Poison\"] = true, [\"Disease\"] = true, }, -- wind\n  },\n  [\"PALADIN\"] = { \n    [1] = { [\"Poison\"] = true, [\"Disease\"] = true, [\"Magic\"] = true, }, -- holy\n    [2] = { [\"Poison\"] = true, [\"Disease\"] = true, }, -- prot\n    [3] = { [\"Poison\"] = true, [\"Disease\"] = true, }, -- ret\n  },\n  [\"PRIEST\"] = { \n    [1] = { [\"Disease\"] = true, [\"Magic\"] = true, }, -- disc\n    [2] = { [\"Disease\"] = true, [\"Magic\"] = true, }, -- holy\n    [3] = { [\"Disease\"] = true, [\"Magic\"] = true, }, -- shadow (magic with mass dispell)\n  }, \n  [\"SHAMAN\"] = { \n    [1] = { [\"Curse\"] = true, }, -- elemental\n    [2] = { [\"Curse\"] = true, }, -- enh\n    [3] = { [\"Curse\"] = true, [\"Magic\"] = true, }, -- resto\n  },\n}\n\n\nfunction SaikoWA_CanDispellTypes() \n  local _, playerClass = UnitClass(\"player\")\n  local playerSpec = GetSpecialization()\n  \n  if playerSpec == nil or can_dispell_table[playerClass] == nil then\n    return {}\n  end\n  \n  return can_dispell_table[playerClass][playerSpec]    \nend\n\nfunction SaikoWA_CanDispellDebuffType(debuffType)\n  return SaikoWA_CanDispellTypes()[debuffType]\nend\n\nfunction SaikoWA_UnitHasDispellableDebuff(unitID) \n  for i=1,40 do\n    local name, icon, count, debuffType, duration, expirationTime, unitCaster, isStealable = UnitDebuff(unitID,i)\n    \n    if name == nil then\n      return false\n    end\n    \n    if debuffType ~= nil and SaikoWA_CanDispellDebuffType(debuffType) then\n      return true\n    end\n  end\nend\n\n\n\nWA_GetFramesCache = WA_GetFramesCache or {}\nif not WA_GetFramesCacheListener then\n  WA_GetFramesCacheListener = CreateFrame(\"Frame\")\n  local f = WA_GetFramesCacheListener\n  f:RegisterEvent(\"PLAYER_REGEN_DISABLED\")\n  f:RegisterEvent(\"PLAYER_REGEN_ENABLED\")\n  f:RegisterEvent(\"GROUP_ROSTER_UPDATE\")\n  f:SetScript(\"OnEvent\", function(self, event, ...)\n      WA_GetFramesCache = {}\n  end)\nend\n\nlocal function GetFrames(target)\n  local function FindButtonsForUnit(frame, target)\n    local results = {}\n    if type(frame) == \"table\" and not frame:IsForbidden() then\n      local type = frame:GetObjectType()\n      if type == \"Frame\" or type == \"Button\" then\n        for _,child in ipairs({frame:GetChildren()}) do\n          for _,v in pairs(FindButtonsForUnit(child, target)) do\n            tinsert(results, v)\n          end\n        end\n      end\n      if type == \"Button\" then\n        local unit = frame:GetAttribute('unit')\n        if unit and frame:IsVisible() then\n          WA_GetFramesCache[frame] = unit\n          if UnitIsUnit(unit, target) then\n            --print(\"F:\", frame:GetName())\n            tinsert(results, frame)\n          end\n        end\n      end\n    end\n    return results\n  end\n  \n  if not UnitExists(target) then\n    if type(target) == \"string\" and target:find(\"Player\") then\n      target = select(6,GetPlayerInfoByGUID(target))\n    else\n      return {}\n    end\n  end \n  \n  local results = {}\n  for frame, unit in pairs(WA_GetFramesCache) do\n    --print(\"from cache:\", frame:GetName())\n    if UnitIsUnit(unit, target) then\n      if frame:GetAttribute('unit') == unit then\n        tinsert(results, frame)\n      else\n        results = {}\n        break\n      end\n    end\n  end\n  \n  return #results > 0 and results or FindButtonsForUnit(UIParent, target)\nend\n\nlocal isElvUI = C_AddOns.IsAddOnLoaded(\"ElvUI\")\nlocal function WhyElvWhy(frame)\n  if isElvUI and frame and frame:GetName():find(\"^ElvUF_\") and frame.Health then\n    return frame.Health\n  else\n    return frame\n  end\nend\n\n\nfunction aura_env.GetFrame(target)\n  local frames = GetFrames(target)\n  if not frames then return nil end\n  for i=1,#frame_priority do\n    for _,frame in pairs(frames) do\n      if (frame:GetName()):find(frame_priority[i]) then\n        return WhyElvWhy(frame)\n      end\n    end\n  end\n  return WhyElvWhy(frames[1])\nend\n\n\nlocal AutoCastShineParentFrame = CreateFrame(\"Frame\")\n\nlocal AutoCastShineTexPool = CreateTexturePool(AutoCastShineParentFrame ,\"ARTWORK\",7)\nlocal FramePoolResetter = function(framePool,frame)\n  frame:SetScript(\"OnUpdate\",nil)\n  local parent = frame:GetParent()\n  if parent.ACShine then\n    parent.ACShine = nil\n    --frame:SetParent(AutoCastShineParentFrame)\n  end\n  if frame.sparkles then\n    for index, sparkle in pairs(frame.sparkles) do\n      AutoCastShineTexPool:Release(sparkle)\n    end\n  end\n  frame.sparkles = {}\n  frame.timers = {0,0,0,0}\n  frame:Hide()\n  frame:ClearAllPoints()\nend\nlocal AutoCastShineFramePool = CreateFramePool(\"Frame\",AutoCastShineParentFrame,nil,FramePoolResetter)\naura_env.AutoCastShineFramePool = AutoCastShineFramePool\n\nlocal ACShine_OnUpdate = function(self,elapsed)\n  local width,height = self:GetSize()\n  local perimeter = 2*(width+height)\n  local bottomlim = height*2+width\n  local rightlim = height+width\n  local space = perimeter/self.N\n  for k,timer in pairs(self.timers) do\n    self.timers[k] = timer+elapsed\n    if timer > self.period*k then\n      timer = timer%(self.period*k)\n    end\n    for i=1,self.N do\n      local pN = i+self.N*(k-1)\n      local position = (space*i+perimeter*timer/(self.period*k))%perimeter\n      if position>bottomlim then\n        self.sparkles[pN]: SetPoint(\"CENTER\",self,\"BOTTOMRIGHT\",-position+bottomlim,0)\n      elseif position>rightlim then\n        self.sparkles[pN]: SetPoint(\"CENTER\",self,\"TOPRIGHT\",0,-position+rightlim)\n      elseif position>height then\n        self.sparkles[pN]: SetPoint(\"CENTER\",self,\"TOPLEFT\",position-height,0)\n      else\n        self.sparkles[pN]: SetPoint(\"CENTER\",self,\"BOTTOMLEFT\",0,position)\n      end\n    end\n  end\nend\n\naura_env.ACShine_Start = function(region,r,g,b,a,N,frequency,scale,xOffset,yOffset)\n  r = r or 0.95\n  g = g or 0.95\n  b = b or 0.32\n  a = a or 1\n  if N then\n    if not(N>0) then\n      N = 4\n    end\n  else\n    N = 4\n  end\n  \n  scale = scale or 1\n  \n  xOffset = xOffset or 0\n  yOffset = yOffset or 0\n  \n  if not region.ACShine then\n    local frame,new =  AutoCastShineFramePool:Acquire()\n    if new then\n      frame.sparkles = {}\n      frame.timers = {0,0,0,0}\n    end\n    region.ACShine = frame\n  end\n  local f = region.ACShine\n  f:SetParent(region)\n  f:SetFrameLevel(region:GetFrameLevel()+4)\n  f:SetPoint(\"TOPLEFT\",region,\"TOPLEFT\",-xOffset,yOffset)\n  f:SetPoint(\"BOTTOMRIGHT\",region,\"BOTTOMRIGHT\",xOffset,-yOffset)\n  f:Show()\n  \n  local width,height = f:GetSize();\n  local space =  2*(width+height)/N\n  local sizes ={13,10,7,4}\n  \n  if frequency then\n    if not(frequency>0) then\n      period = 8\n      \n    else\n      period = 1/frequency\n    end\n  else\n    period = 8\n  end\n  \n  \n  for k,size in pairs(sizes) do\n    for i = 1,N do\n      local pN = i+(k-1)*N\n      if not f.sparkles[pN] then\n        local sparkle,new = AutoCastShineTexPool:Acquire()\n        if new then\n          sparkle:SetTexture(\"Interface\\\\Challenges\\\\challenges-metalglow\")\n          sparkle: SetDesaturated(true)\n          sparkle:SetBlendMode(\"ADD\")\n        end\n        f.sparkles[pN] = sparkle\n        f.sparkles[pN]:SetParent(f)\n      end\n      f.sparkles[pN]: SetSize(size*scale,size*scale)\n      f.sparkles[pN]: SetVertexColor(r,g,b,a)\n      f.sparkles[pN]:Show()\n    end\n  end\n  \n  while #f.sparkles>N*4 do\n    AutoCastShineTexPool:Release(f.sparkles[#f.sparkles])\n    table.remove(f.sparkles)        \n  end\n  \n  f.N = N\n  f.period = period\n  f: SetScript(\"OnUpdate\",ACShine_OnUpdate)\nend\n\naura_env.ACShine_Stop = function(region)\n  if not region.ACShine then\n    return false\n  end\n  AutoCastShineFramePool:Release(region.ACShine)\n  return true\nend\n\n\nhooksecurefunc(WeakAuras, \"OpenOptions\", function()\n    AutoCastShineFramePool:ReleaseAll()\nend)\n\n\naura_env.Glow = function(frame,show)\n  if show then\n    if custom_glow.enable then\n      aura_env.ACShine_Start(\n        frame,\n        custom_glow.red,\n        custom_glow.green,\n        custom_glow.blue,\n        custom_glow.alpha,\n        custom_glow.N,\n        custom_glow.frequency,\n        custom_glow.scale,\n        custom_glow.xOffset,\n        custom_glow.yOffset\n      )\n    else\n      WeakAuras.ShowOverlayGlow(frame)\n    end\n  else\n    if custom_glow.enable then\n      aura_env.ACShine_Stop(frame)\n    else\n      WeakAuras.HideOverlayGlow(frame)\n    end\n  end\nend",
["do_custom"] = true,
},
