["custom"] = "function(CLEU, timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, more1, more2, buffOrDebuff)\n    \n    if subEvent == \"SPELL_AURA_APPLIED\" and buffOrDebuff == \"DEBUFF\" and UnitExists(destName) and bit.band(destFlags, COMBATLOG_OBJECT_TYPE_PLAYER) then\n        \n        local name, _, _, debuffType = WA_GetUnitDebuff(destName, spellID)\n        \n        if  SaikoWA_CanDispellDebuffType(debuffType) then\n            local frame = aura_env.GetFrame(destName)\n            if frame then\n                aura_env.Glow(frame, true)\n            end\n        end\n        \n    elseif (subEvent == \"SPELL_DISPELL_FAILED\" or (subEvent == \"SPELL_AURA_REMOVED\" and buffOrDebuff ==\"DEBUFF\")) and UnitExists(destName) and bit.band(destFlags, COMBATLOG_OBJECT_TYPE_PLAYER) then\n        \n        if not SaikoWA_UnitHasDispellableDebuff(destName) then\n            local frame = aura_env.GetFrame(destName)\n            if frame then\n                aura_env.Glow(frame, false)\n            end\n        end\n    end\nend\n\n\n\n\n\n\n\n\n\n\n\n\n",
